---@class OverseaManageCafeCattyStarUpNode
local OverseaManageCafeCattyStarUpNode = Class('OverseaManageCafeCattyStarUpNode')
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local UIModule = CS.Engine.UI.UIModule
local KTool              = CS.Engine.Lib.KTool
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")

function OverseaManageCafeCattyStarUpNode:__init()
    self.rewardEnv = nil
    self.component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
end

function OverseaManageCafeCattyStarUpNode:__delete()
    self.component = nil
    self.rewardEnv = nil
    self.callBack = nil
end

function OverseaManageCafeCattyStarUpNode:Awake()
    self:InitRewardEnv()
    self:AddUIClick()
end

function OverseaManageCafeCattyStarUpNode:SetCallBack(callBack)
    self.callBack = callBack
end

function OverseaManageCafeCattyStarUpNode:AddUIClick()
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnBntStarUpClick))
end

function OverseaManageCafeCattyStarUpNode:InitRewardEnv()
    if self.CommonGoodsList then
        local env = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
        if env then
            self.rewardEnv = env
        end
    end

--[[    if self.MaterialList then
        local env = CfUtils.GetLuaScr(self.MaterialList, "Game.Behaviours.CommonGoodsList")
        if env then
            self.materialEnv = env
        end
    end]]
end

function OverseaManageCafeCattyStarUpNode:RefreshShow()
    local curStar = self.component:GetMaidCoffeeCattyStarLevel()  --初始为0级  要取下一等级的对应等级
    ---这里不用担心越界 因为如果已经达到最大星级 不会进来这里
    local starVo = MaidCoffeeUtils.GetMaidCoffeeStarUpVo(curStar + 1)
    local maxLevel = nil
    if starVo then
        maxLevel = starVo.rankid
    end

    CfUtils.FillText(self.TxtUpgrade,localize("咖啡馆可升级至_num_星！", { _num_ = curStar + 1} ))

    KTool.SetActive(self.UnlockFunction.gameObject,starVo.ifFunction)
    CfUtils.FillText(self.TxtState,starVo.desc)
    CfUtils.SetUISwitchImage(self.ImgIcon,tonumber(starVo.icon))
    self.rewardEnv:FreshBaseUI(starVo.goods)
    local costs = clone(starVo.costs)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(costs[1].goodsId)
    if goodsVo then
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop.gameObject, costs[1].goodsId, costs[1].goodsNum)
    end
    table.remove(costs,1)
    --self.materialEnv:FreshBaseUI(costs, false, false, true, true,true)
    self:SetStarUpButtonState()
end
---升星
---
---rewards
---list
function OverseaManageCafeCattyStarUpNode:OnBntStarUpClick()
    MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.StarUpBtn)
    local isToMax = self.component:GetIsToMaxStar()
    if isToMax then
        return
    end
    local isLevelUp = self.component:GetCurIsLevelUp()
    if not isLevelUp then
        local isCanStarUp = self.component:GetIsCanStarUp()
        if isCanStarUp then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCattySign, parameters = { callBack = self.callBack } })
        else
            GameUtils.Toast(localize("升星所需材料不足"))
        end
    end
end

function OverseaManageCafeCattyStarUpNode:SetStarUpButtonState()
    local isToMax = self.component:GetIsToMaxStar()
    if isToMax then
        self.FontStyleButton:ResetFontStyle("B17")
        return
    end
    local isLevelUp = self.component:GetCurIsLevelUp()
    if isLevelUp then
        self.FontStyleButton:ResetFontStyle("B17")
        return
    end

    local isCanStarUp = self.component:GetIsCanStarUp()
    local id = isCanStarUp and "B3" or "B17"
    self.FontStyleButton:ResetFontStyle(id)
end

function OverseaManageCafeCattyStarUpNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self.callBack = nil
    self:Delete()
end

return OverseaManageCafeCattyStarUpNode